 for(let warm=0;warm<20;warm++)for(const arm of arms)arm.fn(timer);
 const samples=[];
 for(let pair=0;pair<20;pair++){
  // Rotate which arm starts and alternate the rotation's direction.
  const order=[pair%3,(pair+1)%3,(pair+2)%3];if(pair%2)order.reverse();
  const sample=[0,0,0];
  for(const side of order){elapsed=0;for(let batch=0;batch<3;batch++)arms[side].fn(timer);sample[side]=elapsed/3;}
  samples.push({order,sample});
 }
 output.cases.push({name:arms[0].name,samples});
}
output.loadAfter=os.loadavg();
console.log(JSON.stringify(output));

